/* ── The whole job, through the shim ────────────────────────────────────── */

console.log('\n-- runGP end to end: fixture upstream, SQLite D1, captured R2 --');

await test('a GP run lands rows, writes bundles and logs the call', async () => {
  const db = freshDb();
  const gpBody = raw('sample_gp.json');

  const env = {
    ORBIT_DB: httpDb(db),
    ORBIT_R2: captureR2(),
    ORBIT_KV: memoryKV({ 'spacetrack:cookie': 'chocolatechip=test' }),
    SPACETRACK_IDENTITY: 'a@b.c',
    SPACETRACK_PASSWORD: 'p',
    SPACETRACK_BASE: 'https://spacetrack.test',
  };

  const realFetch = globalThis.fetch;
  globalThis.fetch = async (url) => {
    assert.match(String(url), /spacetrack\.test/, 'the ingest must not reach the real API');
    return new Response(gpBody, { headers: { 'Content-Type': 'application/json' } });
  };
  let report;
  try { report = await runGP(env); } finally { globalThis.fetch = realFetch; }

  assert.ok(report.ok, JSON.stringify(report.steps));
  const ingest = report.steps.find((s) => s.name === 'ingest-gp');
  assert.equal(ingest.rows, JSON.parse(gpBody).length);
  assert.equal(db.prepare('SELECT COUNT(*) c FROM objects').get().c, ingest.rows);

  // The api_calls row is what the budget guard reads on the next run.
  const call = db.prepare("SELECT * FROM api_calls WHERE class = 'gp'").get();
  assert.equal(call.status, 200);
  assert.equal(call.rows, ingest.rows);

  // All group predicates ran against the shim without erroring. The fixture
  // is the twenty oldest catalog objects — Vanguards and Echo debris — so every
  // count is legitimately zero, and buildGroupArtifacts deliberately writes no
  // bundle for an empty group rather than blanking a good one. The bundle write
  // itself is covered below, where a matching row exists.
  const artifacts = report.steps.find((s) => s.name === 'artifacts');
  assert.equal(Object.keys(artifacts.groups).length, Object.keys(GROUPS).length);

  const keys = env.ORBIT_R2.sent.map((s) => s.url);
  assert.ok(keys.some((k) => k.includes('/feed/latest.json')), 'the feed must be written');
});

console.log('\n-- ingestSatcat: skips rows that have not actually changed --');

function mockSatcatFetch(body) {
  return async (url) => {
    assert.match(String(url), /spacetrack\.test/, 'the ingest must not reach the real API');
    return new Response(body, { headers: { 'Content-Type': 'application/json' } });
  };
}

await test('a re-sent SATCAT delta with no real changes writes nothing', async () => {
  const db = freshDb();
  const satcatBody = raw('sample_satcat.json');
  const rows = JSON.parse(satcatBody);

  const env = {
    ORBIT_DB: httpDb(db),
    ORBIT_KV: memoryKV({ 'spacetrack:cookie': 'chocolatechip=test' }),
    SPACETRACK_BASE: 'https://spacetrack.test',
  };

  const realFetch = globalThis.fetch;
  globalThis.fetch = mockSatcatFetch(satcatBody);
  let first;
  try { first = await ingestSatcat(env); } finally { globalThis.fetch = realFetch; }
  assert.equal(first.written, rows.length, 'first run: every row is new, all written');

  // Re-send the identical rows under a new FILE cursor position — as a normal
  // delta re-send would, since Space-Track's window overlaps by design.
  globalThis.fetch = mockSatcatFetch(satcatBody);
  let second;
  try { second = await ingestSatcat(env); } finally { globalThis.fetch = realFetch; }
  assert.equal(second.written, 0, 'second run: nothing actually changed, nothing written');
  assert.equal(second.changes, 0, 'no satcat_change events for an unchanged re-send');
});

await test('a genuinely changed SATCAT row is written; the rest are skipped', async () => {
  const db = freshDb();
  const rows = JSON.parse(raw('sample_satcat.json'));

  const env = {
    ORBIT_DB: httpDb(db),
    ORBIT_KV: memoryKV({ 'spacetrack:cookie': 'chocolatechip=test' }),
    SPACETRACK_BASE: 'https://spacetrack.test',
  };

  const realFetch = globalThis.fetch;
  globalThis.fetch = mockSatcatFetch(JSON.stringify(rows));
  try { await ingestSatcat(env); } finally { globalThis.fetch = realFetch; }

  const bumped = rows.map((r, i) => (i === 0 ? { ...r, OBJECT_NAME: 'RENAMED OBJECT' } : r));
  globalThis.fetch = mockSatcatFetch(JSON.stringify(bumped));
  let out;
  try { out = await ingestSatcat(env); } finally { globalThis.fetch = realFetch; }
  assert.equal(out.written, 1, 'only the row whose fields actually changed should be written');
  assert.equal(
    db.prepare('SELECT OBJECT_NAME FROM satcat WHERE NORAD_CAT_ID = ?').get(Number(rows[0].NORAD_CAT_ID)).OBJECT_NAME,
    'RENAMED OBJECT',
  );
});

await test('a group with members becomes a 3LE bundle carrying the citation', async () => {
  const db = freshDb();
  const env = { ORBIT_DB: httpDb(db), ORBIT_R2: captureR2() };

  // The ISS, by NORAD 25544 — the object the stations group exists for.
  db.prepare(`INSERT INTO objects (NORAD_CAT_ID, OBJECT_NAME, OBJECT_TYPE, TLE_LINE1, TLE_LINE2)
              VALUES (25544, 'ISS (ZARYA)', 'PAYLOAD', '1 25544U 98067A', '2 25544  51.6')`).run();

  const counts = await buildGroupArtifacts(env, { slugs: ['stations'] });
  assert.equal(counts.stations, 1);

  const [{ url, init }] = env.ORBIT_R2.sent;
  assert.ok(url.endsWith('/tle/spacetrack/stations.txt'), url);
  assert.equal(init.headers['x-amz-meta-citation'], CITATION);
  // Bare name line, not TLE_LINE0 — the '0 ' 3LE prefix would label the object
  // "0 ISS (ZARYA)" on the globe.
  assert.equal(init.body.toString('utf8'), 'ISS (ZARYA)\n1 25544U 98067A\n2 25544  51.6\n');
});

